-- =====================================================================
-- MIGRASI 0022 — DATA KALIBRATOR IDA & ESA + TEMPLATE INFUSION PUMP v1 (26 Okt 2026)
-- Supabase : qr-label-kalibrasi (PRODUKSI)
--
-- Bahasa awam: untuk alat Infusion Pump, LKK digital memerlukan "fotokopi sertifikat" dua alat standar:
--   • IDA (Infusion Device Analyzer, CAL-030): tabel aliran (mL/h) dan tekanan penyumbatan (psi)
--   • ESA (Electrical Safety Analyzer, CAL-042): tabel tegangan, resistansi pembumian, isolasi, arus bocor
-- Angka diambil dari sertifikat kedua alat (lewat Master_Infusion_Pump.xlsx), BUKAN dari data contoh di menu aset.
-- Ditambah satu baris template "Infusion Pump" versi 1 agar alatnya muncul di tablet teknisi.
-- Yang TIDAK disentuh: semua baris lama (tabel aset_kalibrator tidak diubah sama sekali; tidak ada yang dihapus).
-- Catatan: CAL-008 kembar CAL-042 (nomor seri & sertifikat sama) dibiarkan; titik ESA dipasang di CAL-042.
-- =====================================================================

-- ===== BLOK 1 — BACKUP =====
create table backup.b20261026_tera_calibrator_points_0022 as table public.tera_calibrator_points;
create table backup.b20261026_tera_device_templates_0022 as table public.tera_device_templates;
select (select count(*) from backup.b20261026_tera_calibrator_points_0022) as titik_tersalin,
       (select count(*) from backup.b20261026_tera_device_templates_0022) as template_tersalin;

-- ===== BLOK 2 — PERUBAHAN =====
begin;
insert into public.tera_calibrator_points
