select v.*, true, now() from (values
  ('CAL-030', 'aliran_mlh', 'mL/h', 'YK.05.02/E.IX/6908/2026', 'SNSU - BSN', date '2026-02-03', date '2027-02-03', '[{"titik":5.21,"koreksiNaik":0,"koreksiTurun":0,"u95Naik":0.06,"u95Turun":0.06,"driftNaik":0,"driftTurun":0},{"titik":10.31,"koreksiNaik":-0.0700000000000003,"koreksiTurun":-0.0700000000000003,"u95Naik":0.11,"u95Turun":0.11,"driftNaik":0,"driftTurun":0},{"titik":49.82,"koreksiNaik":0.119999999999997,"koreksiTurun":0.119999999999997,"u95Naik":0.5,"u95Turun":0.5,"driftNaik":0,"driftTurun":0},{"titik":98.87,"koreksiNaik":-1.88,"koreksiTurun":-1.88,"u95Naik":1,"u95Turun":1,"driftNaik":0,"driftTurun":0},{"titik":294.83,"koreksiNaik":1.92000000000002,"koreksiTurun":1.92000000000002,"u95Naik":3.2,"u95Turun":3.2,"driftNaik":0,"driftTurun":0}]'::jsonb, 'Sertifikat YK.05.02/E.IX/6908/2026 Infusion Device Analyzer IDA-1S s/n 6732052 (BPAFK Jakarta) — nilai dari Master_Infusion_Pump.xlsx sheet Calibrator 1; koreksi = nilai sebenarnya − penunjukan; U95 k=2'),
  ('CAL-030', 'tekanan_psi', 'psi', 'YK.05.02/E.IX/6908/2026', 'SNSU - BSN', date '2026-02-03', date '2027-02-03', '[{"titik":0,"koreksiNaik":0,"koreksiTurun":0,"u95Naik":0.008,"u95Turun":0.008,"driftNaik":0,"driftTurun":0},{"titik":5.02,"koreksiNaik":-0.0199999999999996,"koreksiTurun":-0.0199999999999996,"u95Naik":0.01,"u95Turun":0.01,"driftNaik":0,"driftTurun":0},{"titik":10.04,"koreksiNaik":-0.0399999999999992,"koreksiTurun":-0.0399999999999992,"u95Naik":0.01,"u95Turun":0.01,"driftNaik":0,"driftTurun":0},{"titik":15.06,"koreksiNaik":-0.0600000000000005,"koreksiTurun":-0.0600000000000005,"u95Naik":0.012,"u95Turun":0.012,"driftNaik":0,"driftTurun":0},{"titik":20.05,"koreksiNaik":-0.0500000000000007,"koreksiTurun":-0.0500000000000007,"u95Naik":0.012,"u95Turun":0.012,"driftNaik":0,"driftTurun":0},{"titik":25.05,"koreksiNaik":-0.0500000000000007,"koreksiTurun":-0.0500000000000007,"u95Naik":0.012,"u95Turun":0.012,"driftNaik":0,"driftTurun":0}]'::jsonb, 'Sertifikat YK.05.02/E.IX/6908/2026 Infusion Device Analyzer IDA-1S s/n 6732052 (BPAFK Jakarta) — nilai dari Master_Infusion_Pump.xlsx sheet Calibrator 1; koreksi = nilai sebenarnya − penunjukan; U95 k=2'),
  ('CAL-042', 'tegangan_v', 'V', 'YK.05.02/E.IX/5369/2026', 'LK-110-IDN', date '2026-01-30', date '2027-01-30', '[{"titik":99.9,"koreksiNaik":0.1,"koreksiTurun":0.1,"u95Naik":0.19,"u95Turun":0.19,"driftNaik":0,"driftTurun":0},{"titik":109.9,"koreksiNaik":0.1,"koreksiTurun":0.1,"u95Naik":0.19,"u95Turun":0.19,"driftNaik":0,"driftTurun":0},{"titik":119.9,"koreksiNaik":0.1,"koreksiTurun":0.1,"u95Naik":0.19,"u95Turun":0.19,"driftNaik":0,"driftTurun":0},{"titik":200,"koreksiNaik":0,"koreksiTurun":0,"u95Naik":0.19,"u95Turun":0.19,"driftNaik":0,"driftTurun":0},{"titik":220,"koreksiNaik":0,"koreksiTurun":0,"u95Naik":0.19,"u95Turun":0.19,"driftNaik":0,"driftTurun":0},{"titik":240,"koreksiNaik":0,"koreksiTurun":0,"u95Naik":0.19,"u95Turun":0.19,"driftNaik":0,"driftTurun":0}]'::jsonb, 'Sertifikat YK.05.02/E.IX/5369/2026 Electrical Safety Analyzer ESA612 s/n 6181067 (BPAFK Jakarta) — nilai dari Master_Infusion_Pump.xlsx sheet Calibrator 1; koreksi = nilai sebenarnya − penunjukan; U95 k=2'),
  ('CAL-042', 'resistansi_ohm', 'Ω', 'YK.05.02/E.IX/5369/2026', 'LK-110-IDN', date '2026-01-30', date '2027-01-30', '[{"titik":0.109,"koreksiNaik":-0.009,"koreksiTurun":-0.009,"u95Naik":0.0025,"u95Turun":0.0025,"driftNaik":0,"driftTurun":0},{"titik":0.209,"koreksiNaik":-0.009,"koreksiTurun":-0.009,"u95Naik":0.0026,"u95Turun":0.0026,"driftNaik":0,"driftTurun":0},{"titik":0.509,"koreksiNaik":-0.009,"koreksiTurun":-0.009,"u95Naik":0.0025,"u95Turun":0.0025,"driftNaik":0,"driftTurun":0},{"titik":1.011,"koreksiNaik":-0.011,"koreksiTurun":-0.011,"u95Naik":0.0025,"u95Turun":0.0025,"driftNaik":0,"driftTurun":0}]'::jsonb, 'Sertifikat YK.05.02/E.IX/5369/2026 Electrical Safety Analyzer ESA612 s/n 6181067 (BPAFK Jakarta) — nilai dari Master_Infusion_Pump.xlsx sheet Calibrator 1; koreksi = nilai sebenarnya − penunjukan; U95 k=2'),
  ('CAL-042', 'isolasi_mohm', 'MΩ', 'YK.05.02/E.IX/5369/2026', 'LK-110-IDN', date '2026-01-30', date '2027-01-30', '[{"titik":1,"koreksiNaik":0,"koreksiTurun":0,"u95Naik":0.058,"u95Turun":0.058,"driftNaik":0,"driftTurun":0},{"titik":10,"koreksiNaik":0,"koreksiTurun":0,"u95Naik":0.058,"u95Turun":0.058,"driftNaik":0,"driftTurun":0}]'::jsonb, 'Sertifikat YK.05.02/E.IX/5369/2026 Electrical Safety Analyzer ESA612 s/n 6181067 (BPAFK Jakarta) — nilai dari Master_Infusion_Pump.xlsx sheet Calibrator 1; koreksi = nilai sebenarnya − penunjukan; U95 k=2'),
  ('CAL-042', 'arus_bocor_ua', 'µA', 'YK.05.02/E.IX/5369/2026', 'LK-110-IDN', date '2026-01-30', date '2027-01-30', '[{"titik":9.4,"koreksiNaik":0.6,"koreksiTurun":0.6,"u95Naik":0.62,"u95Turun":0.62,"driftNaik":0,"driftTurun":0},{"titik":49.4,"koreksiNaik":0.6,"koreksiTurun":0.6,"u95Naik":0.62,"u95Turun":0.62,"driftNaik":0,"driftTurun":0},{"titik":99.7,"koreksiNaik":0.3,"koreksiTurun":0.3,"u95Naik":0.62,"u95Turun":0.62,"driftNaik":0,"driftTurun":0},{"titik":499,"koreksiNaik":1,"koreksiTurun":1,"u95Naik":0.79,"u95Turun":0.79,"driftNaik":0,"driftTurun":0}]'::jsonb, 'Sertifikat YK.05.02/E.IX/5369/2026 Electrical Safety Analyzer ESA612 s/n 6181067 (BPAFK Jakarta) — nilai dari Master_Infusion_Pump.xlsx sheet Calibrator 1; koreksi = nilai sebenarnya − penunjukan; U95 k=2')
) as v(aset_kalibrator_id, parameter, satuan, nomor_sertifikat, tertelusur, tanggal_kalibrasi, berlaku_sampai, points, sumber);

insert into public.tera_device_templates (kode_alat, nama, versi, kop, definition, aktif)
values ('infusion_pump', 'Infusion Pump', 1, 'NON_KAN', '{"tipe":"pompa","kode_alat":"infusion_pump","nama":"Infusion Pump","versi":1,"sumber":"Master_Infusion_Pump.xlsx (26 Okt 2026) + KMK-MK-053.0; fisik & fungsi semua kotak, aliran ≤ 200 mL/h, penyumbatan ≤ 20 psi","metode":"KMK-MK-053.0","kop":"NON_KAN","keselamatan_listrik":"wajib","identitas":{"resolusi":{"satuan":"mL/h","pilihan":[0.1,1,0.01]},"jenisSkala":["Digital","Analog"]},"identitasBidang":[{"id":"merek","label":"Merek","jenis":"teks","maksPanjang":80},{"id":"tipe","label":"Tipe","jenis":"teks","maksPanjang":80},{"id":"noSeri","label":"Nomor seri","jenis":"teks","maksPanjang":80},{"id":"rentangUkur","label":"Rentang ukur (mis. 1 - 999 mL/h)","jenis":"teks","maksPanjang":40},{"id":"resolusi","label":"Resolusi","jenis":"resolusi","satuan":"mL/h"},{"id":"jenisSkala","label":"Jenis skala","jenis":"skala"},{"id":"tanggalPenerimaan","label":"Tanggal penerimaan alat","jenis":"tanggal"},{"id":"ruang","label":"Ruangan","jenis":"teks","maksPanjang":80}],"standar":[{"peran":"ida","judul":"Infusion Device Analyzer (IDA)","parameter":["aliran_mlh","tekanan_psi"],"wajib":true},{"peran":"esa","judul":"Electrical Safety Analyzer (ESA)","parameter":["tegangan_v","resistansi_ohm","isolasi_mohm","arus_bocor_ua"],"wajib":true},{"peran":"termohigrometer","judul":"Termohigrometer","parameter":["suhu_c","kelembaban_rh"],"wajib":true,"hanyaRekomendasi":true}],"fisik":[{"id":"badan","judul":"Badan dan Permukaan / Enclosure and its Surfaces"},{"id":"kontrol","judul":"Kontrol dan Indikator / Control and indicator"},{"id":"kabel","judul":"Kabel dan Aksesori / Wire and acessories"}],"pilihanFisik":{"fisik":["Baik","Tidak Baik"],"fungsi":["Berfungsi","Tidak Berfungsi"]},"listrik":[{"id":"tegangan","judul":"Tegangan Catu Daya / Mains Voltage","satuan":"V","kalibrator":"tegangan","uji":{"jenis":"sekitar","nominal":220,"batas":22},"diBawahTabel":"ujung","toleransiTeks":"220 ±10 %"},{"id":"resistansi_pembumian","judul":"Resistansi Pembumian Protektif / Protective Earth Resistance","satuan":"Ω","kalibrator":"resistansi","uji":{"jenis":"maksimum","batas":0.3},"diBawahTabel":"ujung","toleransiTeks":"≤ 0,3"},{"id":"resistansi_isolasi","judul":"Isolasi Resistansi / Insulation of Resistance","satuan":"MΩ","kalibrator":"isolasi","uji":{"jenis":"minimum","batas":2},"diBawahTabel":"ujung","toleransiTeks":"≥ 2"},{"id":"arus_bocor","judul":"Arus Bocor Pembumian / Earth Leakage Current","satuan":"µA","kalibrator":"arus_bocor","uji":{"jenis":"maksimum","batas":500},"diBawahTabel":"proporsional","toleransiTeks":"≤ 500"}],"kinerja":{"titikAliran":[25,50,100,150,200],"pengulangan":6,"toleransiAliranPersen":0.1,"sumbat":{"batas":20,"banding":"<=","resolusiTetap":0.01,"settingBawaan":100},"driftPersen":0.1,"derajatBebas":{"sertifikat":60,"resolusi":50,"drift":50},"pembagiResolusi":{"Analog":2.449489742783178,"Digital":1.7320508075688772},"desimalCetak":2,"minimalPersenAliran":0.7},"skor":{"fisik":{"minimalPersen":0.7,"nilai":10},"listrik":{"nilai":40},"kinerja":{"nilai":50},"laikBila":{"banding":">=","batas":90}},"sertifikat":{"tata_letak":"report_all_infusion_pump","halaman":3}}'::jsonb, true);
commit;

-- ===== BLOK 3 — CEK (harapan: semua true) =====
select 'titik baru: 6 baris aktif (IDA 2 + ESA 4) dengan jumlah titik 5/4/2/4/6/6 (urut nama parameter)' cek,
       (select string_agg(jsonb_array_length(points)::text, '/' order by parameter) = '5/4/2/4/6/6' from public.tera_calibrator_points
         where aset_kalibrator_id in ('CAL-030','CAL-042') and aktif) hasil
union all select 'IDA aliran titik pertama: penunjukan 5,21 koreksi 0 U95 0,06',
       (select (points->0->>'titik')::numeric = 5.21 and (points->0->>'u95Naik')::numeric = 0.06 from public.tera_calibrator_points where aset_kalibrator_id='CAL-030' and parameter='aliran_mlh' and aktif)
union all select 'template infusion_pump v1 aktif, Non-KAN', (select count(*) = 1 from public.tera_device_templates where kode_alat='infusion_pump' and versi=1 and aktif and kop='NON_KAN')
union all select 'Sphygmo & baris lama tidak berubah',
       (select count(*) = 0 from public.tera_calibrator_points t join backup.b20261026_tera_calibrator_points_0022 b using (id) where t.points <> b.points or t.aktif <> b.aktif)
       and (select count(*) = 0 from public.tera_device_templates t join backup.b20261026_tera_device_templates_0022 b using (id) where t.definition <> b.definition or t.aktif <> b.aktif);

